-- docs/superpowers/plans/2026-11-18-permissions-server-enforcement.md Task 7.
--
-- Rewrites the SELECT RLS policies on suppliers and supplier_transactions to
-- gate on suppliers.manage (via app_has_permission() from Task 1) instead of
-- a bare tenant_id check. True current/live policy names, confirmed by
-- grepping ALL migrations (not trusting the brief's claim):
--   suppliers_tenant_read (generated by the tenant_tables loop in
--     20240601000000_track_base_schema.sql; never overridden since --
--     previously: app_is_super_admin() OR tenant_id = app_current_tenant_id())
--   supplier_transactions_tenant_select (created in
--     20261121000000_supplier_balance_role_guard.sql, which replaced the
--     earlier supplier_transactions_tenant_isolation FOR ALL policy; never
--     overridden since -- previously: app_is_super_admin() OR
--     tenant_id = app_current_tenant_id())
--
-- payments.view_prices is explicitly OUT of scope for this task (see
-- task-7-brief.md Step 3 note -- not one of the plan's 11 approved keys).
-- payments' SELECT policy is left untouched.
--
-- NOTE on assertion style: a SELECT blocked by RLS returns 0 rows silently
-- (no exception) -- same failure mode as the Task 6 DELETE policies. So
-- denial scenarios assert row count = 0 via is() on SELECT count(*), not
-- throws_like/throws_matching.
--
-- Also preserves tenant isolation: a staff member from a DIFFERENT tenant,
-- even with suppliers.manage=true, must still see 0 rows for the first
-- tenant's data.
--
-- Run with: npx supabase db query --linked --file <this file>
-- (supabase test db --linked needs Docker, which is down on this machine.)
BEGIN;
SELECT plan(8);

-- db query --linked only surfaces the LAST statement's result set, so
-- collect each assertion's TAP line here and print them all together with
-- finish() at the end instead of relying on each SELECT's own output.
CREATE TEMP TABLE test_output (seq INT GENERATED ALWAYS AS IDENTITY, line TEXT);
GRANT INSERT, SELECT ON test_output TO authenticated;

-- Fixtures: two tenants; tenant A has one supplier + one supplier_transaction
-- row; a cashier in tenant A (role_id IS NULL, so suppliers.manage=false
-- from the default table); an admin in tenant A (role_id IS NULL, so
-- suppliers.manage=true); an admin in tenant B (also suppliers.manage=true,
-- but wrong tenant -- used for the tenant-isolation check).
SET session_replication_role = replica;

INSERT INTO public.tenants (id, name, owner_email, phone)
VALUES
  ('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Select Policies Perm Test Tenant A', 'owner-a@select-policies-perm.test.invalid', '0500000008'),
  ('ffffffff-ffff-ffff-ffff-ffffffffffff', 'Select Policies Perm Test Tenant B', 'owner-b@select-policies-perm.test.invalid', '0500000009');

INSERT INTO public.staff (id, tenant_id, uid, name, email, role, role_id, status)
VALUES
  ('bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb', 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
   'cccccccc-cccc-cccc-cccc-cccccccccccc', 'Test Cashier', 'cashier@select-policies-perm.test.invalid', 'cashier', NULL, 'active'),
  ('dddddddd-dddd-dddd-dddd-dddddddddddd', 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
   'eeeeeeee-eeee-eeee-eeee-eeeeeeeeeeee', 'Test Admin', 'admin@select-policies-perm.test.invalid', 'admin', NULL, 'active'),
  ('99999999-9999-9999-9999-999999999999', 'ffffffff-ffff-ffff-ffff-ffffffffffff',
   '88888888-8888-8888-8888-888888888888', 'Test Admin Other Tenant', 'admin-b@select-policies-perm.test.invalid', 'admin', NULL, 'active'),
  ('12121212-1212-1212-1212-121212121212', 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
   '34343434-3434-3434-3434-343434343434', 'Test Branch Manager', 'branch-manager@select-policies-perm.test.invalid', 'branch_manager', NULL, 'active'),
  ('56565656-5656-5656-5656-565656565656', 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
   '78787878-7878-7878-7878-787878787878', 'Test Warehouse Manager', 'warehouse-manager@select-policies-perm.test.invalid', 'warehouse_manager', NULL, 'active');

INSERT INTO public.suppliers (id, tenant_id, name, phone)
VALUES ('11111111-1111-1111-1111-111111111111', 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'Test Supplier', '0500000010');

INSERT INTO public.supplier_transactions (id, tenant_id, supplier_id, type, credit, reference_number)
VALUES ('22222222-2222-2222-2222-222222222222', 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
        '11111111-1111-1111-1111-111111111111', 'payment', 100, 'REF-SELPOL-1');

SET session_replication_role = DEFAULT;

-- Scenario 1: cashier (suppliers.manage=false) selects from suppliers --
-- RLS silently excludes the row.
SET LOCAL ROLE authenticated;
SET LOCAL request.jwt.claims = '{"sub":"cccccccc-cccc-cccc-cccc-cccccccccccc"}';
INSERT INTO test_output (line) SELECT is(
  (SELECT count(*) FROM public.suppliers WHERE tenant_id = 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'),
  0::bigint,
  'cashier (suppliers.manage=false) selecting suppliers -- RLS blocks it, 0 rows'
);

-- Scenario 2: admin (suppliers.manage=true) selects from suppliers --
-- sees the row.
SET LOCAL request.jwt.claims = '{"sub":"eeeeeeee-eeee-eeee-eeee-eeeeeeeeeeee"}';
INSERT INTO test_output (line) SELECT is(
  (SELECT count(*) FROM public.suppliers WHERE tenant_id = 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'),
  1::bigint,
  'admin (suppliers.manage=true) selecting suppliers -- sees the row'
);

-- Scenario 3: cashier (suppliers.manage=false) selects from
-- supplier_transactions -- RLS silently excludes the row.
SET LOCAL request.jwt.claims = '{"sub":"cccccccc-cccc-cccc-cccc-cccccccccccc"}';
INSERT INTO test_output (line) SELECT is(
  (SELECT count(*) FROM public.supplier_transactions WHERE tenant_id = 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'),
  0::bigint,
  'cashier (suppliers.manage=false) selecting supplier_transactions -- RLS blocks it, 0 rows'
);

-- Scenario 4: admin (suppliers.manage=true) selects from
-- supplier_transactions -- sees the row.
SET LOCAL request.jwt.claims = '{"sub":"eeeeeeee-eeee-eeee-eeee-eeeeeeeeeeee"}';
INSERT INTO test_output (line) SELECT is(
  (SELECT count(*) FROM public.supplier_transactions WHERE tenant_id = 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'),
  1::bigint,
  'admin (suppliers.manage=true) selecting supplier_transactions -- sees the row'
);

-- Scenario 5: admin from tenant B (suppliers.manage=true) selects tenant
-- A's suppliers row -- tenant isolation must still hold even with the
-- permission granted.
SET LOCAL request.jwt.claims = '{"sub":"88888888-8888-8888-8888-888888888888"}';
INSERT INTO test_output (line) SELECT is(
  (SELECT count(*) FROM public.suppliers WHERE tenant_id = 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'),
  0::bigint,
  'admin from a different tenant (suppliers.manage=true) selecting suppliers -- tenant isolation blocks it, 0 rows'
);

-- Scenario 6: same other-tenant admin selects tenant A's
-- supplier_transactions row -- tenant isolation must still hold.
INSERT INTO test_output (line) SELECT is(
  (SELECT count(*) FROM public.supplier_transactions WHERE tenant_id = 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'),
  0::bigint,
  'admin from a different tenant (suppliers.manage=true) selecting supplier_transactions -- tenant isolation blocks it, 0 rows'
);

-- Scenario 7: branch_manager (role_id IS NULL, so suppliers.manage=true via
-- the default table -- confirmed in Task 1's matrix,
-- 20261205000000_app_has_permission.sql) selects from suppliers -- sees the
-- row. branch_manager/warehouse_manager are the two roles whose
-- suppliers.manage access is the actual behavior change Task 5 introduced
-- via the RPCs; this proves they can also SELECT the data they can now act
-- on (I3 gap -- previously only cashier/admin were covered here).
SET LOCAL request.jwt.claims = '{"sub":"34343434-3434-3434-3434-343434343434"}';
INSERT INTO test_output (line) SELECT is(
  (SELECT count(*) FROM public.suppliers WHERE tenant_id = 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'),
  1::bigint,
  'branch_manager (suppliers.manage=true by default) selecting suppliers -- sees the row'
);

-- Scenario 8: warehouse_manager (role_id IS NULL, so suppliers.manage=true
-- via the default table) selects from supplier_transactions -- sees the
-- row.
SET LOCAL request.jwt.claims = '{"sub":"78787878-7878-7878-7878-787878787878"}';
INSERT INTO test_output (line) SELECT is(
  (SELECT count(*) FROM public.supplier_transactions WHERE tenant_id = 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'),
  1::bigint,
  'warehouse_manager (suppliers.manage=true by default) selecting supplier_transactions -- sees the row'
);

INSERT INTO test_output (line) SELECT * FROM finish();
SELECT line FROM test_output ORDER BY seq;
ROLLBACK;
